const clean = raw.replace(/```json|```/g, '').trim();
const parsed = JSON.parse(clean);

return [{
  json: {
    name: parsed.name,
    description: parsed.description,
    urgency: parsed.urgency,
    priority: parsed.priority,
    type: parsed.type,
    device: parsed.device,
    location: parsed.location
  }
}];

